sp_widget.client_script:
api.controller = function() {
    var c = this;
    c.selectedAccount = null;

    var now = new Date();
    var currentMonth = now.getMonth() + 1;
    var currentYear = now.getFullYear();

    c.filter = {
        fromMonth: currentMonth,
        fromYear: currentYear,
        toMonth: currentMonth,
        toYear: currentYear,
        searchText: ''
    };

    c.months = [
        { value: 1, label: 'January' },
        { value: 2, label: 'February' },
        { value: 3, label: 'March' },
        { value: 4, label: 'April' },
        { value: 5, label: 'May' },
        { value: 6, label: 'June' },
        { value: 7, label: 'July' },
        { value: 8, label: 'August' },
        { value: 9, label: 'September' },
        { value: 10, label: 'October' },
        { value: 11, label: 'November' },
        { value: 12, label: 'December' }
    ];

    c.years = [];
    for (var y = 2020; y <= 2030; y++) {
        c.years.push(y);
    }

    c.selectAccount = function(acct) {
        c.selectedAccount = acct;
        c.loadTransactions();
    };

    c.clearSelection = function() {
        c.selectedAccount = null;
        c.data.transactions = undefined;
    };

    c.loadTransactions = function() {
        if (!c.selectedAccount) return;

        var fromMonth = ('0' + c.filter.fromMonth).slice(-2);
        var fromDate = c.filter.fromYear + '-' + fromMonth + '-01';

        var toMonth = c.filter.toMonth;
        var toYear = c.filter.toYear;
        var lastDay = new Date(toYear, toMonth, 0).getDate();
        var toMonthStr = ('0' + toMonth).slice(-2);
        var toDate = toYear + '-' + toMonthStr + '-' + ('0' + lastDay).slice(-2);

        c.server.get({
            action: 'getTransactions',
            account_id: c.selectedAccount.sys_id,
            from_date: fromDate,
            to_date: toDate,
            search_text: c.filter.searchText
        }).then(function(response) {
            c.data.transactions = response.data.transactions;
        });
    };

    c.applyFilters = function() {
        c.loadTransactions();
    };
};

sp_widget.css:
.my-accounts-widget {
    .panel-title {
        font-size: $sp-text-lg;
        color: $text-color;
    }

    .cursor-pointer {
        cursor: pointer;
    }

    .table > tbody > tr.active > td {
        background-color: lighten($brand-primary, 45%);
    }

    .table > tbody > tr:hover > td {
        background-color: lighten($brand-primary, 50%);
    }

    .transactions-section {
        margin-top: 15px;
    }

    .transaction-filters {
        margin-bottom: 15px;
        padding-bottom: 15px;
        border-bottom: 1px solid lighten($text-muted, 30%);

        .form-group {
            margin-right: 10px;
            margin-bottom: 5px;

            label {
                margin-right: 5px;
                color: $text-color;
                font-size: $sp-text-xs;
            }

            .form-control {
                font-size: $sp-text-xs;
            }
        }

        .btn-primary {
            background-color: $brand-primary;
            border-color: $brand-primary;
        }
    }

    .transactions-table {
        font-size: $sp-text-xs;

        th {
            color: $text-muted;
            font-weight: 600;
            text-transform: uppercase;
            font-size: $sp-text-xs;
        }

        td {
            color: $text-color;
            vertical-align: middle;
        }
    }

    .empty-state {
        padding: 20px;
        color: $text-muted;
        font-size: $sp-text-xs;
    }
}

sp_widget.script:
(function() {
    if (input && input.action === 'getTransactions') {
        data.transactions = [];
        var txnGr = new GlideRecord('x_274351_finance_0_txn');
        txnGr.addQuery('account', input.account_id);
        if (input.from_date) {
            txnGr.addQuery('timestamp', '>=', input.from_date);
        }
        if (input.to_date) {
            txnGr.addQuery('timestamp', '<=', input.to_date);
        }
        if (input.search_text) {
            txnGr.addQuery('description', 'CONTAINS', input.search_text);
        }
        txnGr.orderByDesc('timestamp');
        txnGr.setLimit(100);
        txnGr.query();
        while (txnGr.next()) {
            data.transactions.push({
                sys_id: txnGr.getUniqueValue(),
                number: txnGr.getValue('number'),
                timestamp: txnGr.getDisplayValue('timestamp'),
                type: txnGr.getDisplayValue('type'),
                description: txnGr.getValue('description'),
                amount: parseFloat(txnGr.getValue('amount') || 0).toFixed(2),
                balance_after: parseFloat(txnGr.getValue('balance_after') || 0).toFixed(2),
                status: txnGr.getDisplayValue('status')
            });
        }
        return;
    }

    data.accounts = [];
    data.isManager = gs.hasRole('x_274351_finance_0.manager') && !gs.hasRole('x_274351_finance_0.administrator');

    var gr = new GlideRecord('x_274351_finance_0_accounts');
    gr.addQuery('holder', gs.getUserID());
    gr.orderBy('number');
    gr.setLimit(50);
    gr.query();
    while (gr.next()) {
        data.accounts.push({
            sys_id: gr.getUniqueValue(),
            number: gr.getValue('number'),
            account_type: gr.getDisplayValue('account_type'),
            holder_name: gr.getDisplayValue('holder'),
            balance: parseFloat(gr.getValue('balance') || 0).toFixed(2),
            active: gr.getValue('active') == '1' || gr.getValue('active') == 'true'
        });
    }
})();
